import { MeshBasicNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { uv, vec2, color, mix, smoothstep, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const {
    Group, Mesh, PlaneGeometry, SphereGeometry, CylinderGeometry, CircleGeometry,
    Box3, Vector3, DirectionalLight, PointLight,
  } = ctx.THREE;

  const root = new Group();
  const timelines = [];
  const primHandles = [];
  const disposables = [];

  const colors = config.intent?.visualSpec?.colors ?? {};
  const BG = colors.background ?? '#0b0b10';
  const SURF = colors.surface ?? '#14141a';
  const INK = colors.ink ?? '#16161d';
  const PAPER = colors.paper ?? '#e8ecf2';
  const ACCENT = colors.accent ?? '#ff2a38';

  // ---------------------------------------------------------------- backdrop
  const bgGeo = new PlaneGeometry(7, 6);
  const bgMat = new MeshBasicNodeMaterial();
  {
    const vy = uv().y;
    const c1 = mix(color(BG), color('#101017'), smoothstep(0.0, 0.65, vy));
    const c2 = mix(c1, color(INK), smoothstep(0.65, 1.0, vy));
    const cd = uv().sub(vec2(0.5, 0.55)).length();
    const lift = float(1.0).sub(smoothstep(0.0, 0.62, cd)).mul(0.055);
    bgMat.colorNode = c2.add(lift);
  }
  const backdrop = new Mesh(bgGeo, bgMat);
  backdrop.position.set(0, 0, -3);
  root.add(backdrop);
  disposables.push(bgGeo, bgMat);

  // ---------------------------------------------------------------- lighting (node-local rim + accent)
  const rim = new DirectionalLight(PAPER, 0.8);
  rim.position.set(-3, 2.2, -4);
  root.add(rim);

  const jewelGlow = new PointLight(ACCENT, 1.1, 4.5, 2);
  jewelGlow.position.set(0.15, 0.1, 1.1);
  root.add(jewelGlow);

  // ---------------------------------------------------------------- contact shadow
  const shGeo = new CircleGeometry(0.5, 48);
  const shMat = new MeshBasicNodeMaterial();
  shMat.colorNode = color('#000000');
  const shD = uv().sub(vec2(0.5)).length().mul(2.0);
  shMat.opacityNode = float(1.0).sub(smoothstep(0.15, 1.0, shD)).mul(0.5);
  shMat.transparent = true;
  shMat.depthWrite = false;
  const shadow = new Mesh(shGeo, shMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.scale.set(2.6, 1.2, 1);
  shadow.position.set(0.35, -1.2, 0);
  root.add(shadow);
  disposables.push(shGeo, shMat);

  // ---------------------------------------------------------------- materials
  const steel = new MeshPhysicalNodeMaterial({
    color: PAPER,
    roughness: 0.5,
    metalness: 0.55,
    clearcoat: 0.2,
    clearcoatRoughness: 0.3,
  });
  steel.anisotropy = 0.7;
  disposables.push(steel);

  const inkMat = new MeshPhysicalNodeMaterial({
    color: INK,
    roughness: 0.6,
    metalness: 0.3,
  });
  disposables.push(inkMat);

  const jewelMat = new MeshPhysicalNodeMaterial({
    color: ACCENT,
    transmission: 0.6,
    ior: 1.76,
    thickness: 0.2,
    roughness: 0.15,
    metalness: 0.0,
    emissive: ACCENT,
    emissiveIntensity: 1.8,
  });
  disposables.push(jewelMat);

  // ---------------------------------------------------------------- gear assembly
  const assembly = new Group();
  root.add(assembly);

  const primaryPivot = new Group();          // spins at 0.08 rad/s
  primaryPivot.position.set(0, 0, 0);
  assembly.add(primaryPivot);

  const secondaryPivot = new Group();        // spins at -0.142 rad/s
  secondaryPivot.position.set(1.15, 0.35, -0.1);
  secondaryPivot.rotation.z = Math.PI / 16;  // phase lock so teeth never intersect
  assembly.add(secondaryPivot);

  // arbor shafts (z-length 0.8, radius 0.05, ink)
  const arborGeo = new CylinderGeometry(0.05, 0.05, 0.8, 24);
  disposables.push(arborGeo);
  for (const pivot of [primaryPivot, secondaryPivot]) {
    const arbor = new Mesh(arborGeo, inkMat);
    arbor.rotation.x = Math.PI / 2;
    pivot.add(arbor);
  }

  // jewel pivot at primary hub
  const jewelGeo = new SphereGeometry(0.12, 32, 24);
  const jewel = new Mesh(jewelGeo, jewelMat);
  jewel.position.set(0, 0, 0.24);
  primaryPivot.add(jewel);
  disposables.push(jewelGeo);

  // gears from GLB
  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    if (!gltf || !gltf.scene) return;

    const src = gltf.scene;
    src.traverse((o) => { if (o.isMesh) o.material = steel; });

    const box = new Box3().setFromObject(src);
    const size = new Vector3();
    box.getSize(size);
    const diameter = Math.max(size.x, size.y) || 1;

    const gearA = src;
    const sA = 1.6 / diameter;
    gearA.scale.setScalar(sA);
    primaryPivot.add(gearA);

    const gearB = src.clone(true);
    gearB.traverse((o) => { if (o.isMesh) o.material = steel; });
    const sB = 0.9 / diameter;
    gearB.scale.setScalar(sB);
    secondaryPivot.add(gearB);

    // meshing rotation: 16:9 ratio, primary 0.08 rad/s, secondary -0.142 rad/s
    const tw1 = gsap.to(primaryPivot.rotation, {
      z: `+=${Math.PI * 2}`,
      duration: (Math.PI * 2) / 0.08,
      ease: 'none',
      repeat: -1,
    });
    const tw2 = gsap.to(secondaryPivot.rotation, {
      z: `-=${Math.PI * 2}`,
      duration: (Math.PI * 2) / 0.142,
      ease: 'none',
      repeat: -1,
    });
    timelines.push(tw1, tw2);

    // entrance: rise-in + weighted settle
    const enter = gsap.timeline();
    enter.from(assembly.position, { y: -0.35, duration: 0.7, ease: 'power3.out' }, 0);
    enter.fromTo(assembly.scale,
      { x: 0.96, y: 0.96, z: 0.96 },
      { x: 1.04, y: 1.04, z: 1.04, duration: 0.45, ease: 'power2.out' }, 0);
    enter.to(assembly.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0.45);
    timelines.push(enter);
  });

  // ---------------------------------------------------------------- text
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textNodes = [];
  for (const item of items) {
    if (item.role === 'headline') {
      const h = ctx.fontAtlas.createText(item.text, {
        fontSize: item.typography?.fontSize ?? 68,
        color: PAPER,
        align: 'center',
      });
      h.position.set(0, -1.7, 0.4);
      root.add(h);
      textNodes.push(h);
    } else if (item.role === 'caption') {
      const c = ctx.fontAtlas.createText(item.text, {
        fontSize: item.typography?.fontSize ?? 18,
        color: PAPER,
        align: 'center',
        letterSpacingPx: Math.round((item.typography?.fontSize ?? 18) * 0.08 * 100) / 100,
      });
      c.position.set(0, -2.1, 0.4);
      root.add(c);
      textNodes.push(c);
    }
  }
  // text fade-up entrance
  for (let i = 0; i < textNodes.length; i++) {
    const tn = textNodes[i];
    const tw = gsap.from(tn.position, {
      y: tn.position.y - 0.2,
      duration: 0.5,
      ease: 'power2.out',
      delay: 0.2 + i * 0.08,
    });
    timelines.push(tw);
  }

  // ---------------------------------------------------------------- cinematic primitives
  for (const prim of config.cinematicPrimitives ?? []) {
    const fn = ctx.primitives[prim.name];
    if (fn) {
      const handle = fn(root, prim.params ?? {});
      if (handle) primHandles.push(handle);
    }
  }

  // ---------------------------------------------------------------- lifecycle
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    for (const t of timelines) { if (t && t.kill) t.kill(); }
    for (const h of primHandles) { if (h && h.cleanup) h.cleanup(); }
    for (const d of disposables) { if (d && d.dispose) d.dispose(); }
    root.traverse((o) => {
      if (o.isMesh) {
        if (o.geometry && o.geometry.dispose) o.geometry.dispose();
        if (o.material && o.material.dispose) o.material.dispose();
      }
    });
  };

  return root;
}
